This is because partial with async functions isn't supported in Depends: issue #10720
You can workaround it by rewriting get_profile_load_options like this:
def get_profile_load_options(*load_options) -> Callable:
    print(f"UTILS get_profile_load_options {load_options=}")

    async def parametrized(
        db: AsyncSession = Depends(get_db),
        profile_id: int | None = None,
    ) -> Profile:
        return await get_current_profile(
            db=db, profile_id=profile_id, load_options=list(load_options)
        )
    return parametrized
Or this:
def get_profile_load_options(*load_options):
    print(f"UTILS get_profile_load_options {load_options=}")

    async def get_current_profile(
        db: AsyncSession = Depends(get_db),
        profile_id: int | None = None,
    ) -> Profile:
        nonlocal load_options
        if not load_options:
            load_options = []

        profile = await db.scalar(
            select(Profile).filter(Profile.id == profile_id).options(*load_options)
        )
        if not profile:
            raise HTTPException(status_code=404, detail="Profile not found")
        return profile

    return get_current_profile

As far as I know you can not specify the order of parameters in openapi schema by changing their order in function definition..
But you can modify openapi schema:
from typing import cast
from fastapi import Depends, FastAPI, Form
from fastapi.openapi.utils import get_openapi

app = FastAPI()


def validate_document_params(
    document_id: str = Form(),
    env_id: str = Form(),
):
    return "test"


@app.get("/test")
async def test(
    document_params: str = Depends(validate_document_params), model_name: str = Form()
):
    return {document_params, model_name}


FIRST_ORDER_FIELDS = {"document_id", "env_id"}


def custom_openapi():
    if app.openapi_schema:
        return app.openapi_schema
    openapi_schema = get_openapi(
        title=app.title,
        version=app.version,
        summary=app.summary,
        description=app.description,
        routes=app.routes,
    )

    for schema in cast(dict, openapi_schema["components"]["schemas"]).values():
        properties: dict = schema["properties"]
        schema["properties"] = dict(
            sorted(
                properties.items(),
                key=lambda x: x[0] in FIRST_ORDER_FIELDS,
                reverse=True,
            ),
        )

    app.openapi_schema = openapi_schema
    return app.openapi_schema

app.openapi = custom_openapi

