from abc import ABC, abstractmethod
from typing import Annotated

from fastapi import Depends, FastAPI, Header

app = FastAPI()


def get_user_browser(user_agent: str = Header(default="")):
    browser = user_agent.split(" ")[0]
    return browser


def get_greeting_message(browser: Annotated[str, Depends(get_user_browser)]):
    return f"Hello, {browser} user!"


class GreetingGenerator(ABC):
    def format_greeting(self, message: str):
        return {"message": message}

    @abstractmethod
    def __call__(self, message: str):
        raise NotImplementedError()


class GreetingGenerator_1(GreetingGenerator):
    def __call__(self, message: str = Depends(get_greeting_message)):
        return self.format_greeting(message)


greeter = GreetingGenerator_1()


@app.get("/hello")
async def hello(greeting: Annotated[dict, Depends(greeter)]):
    return greeting


So, you can implement common logic (like response formatting) in GreetingGenerator, but you will still need to create new class for every greeting provider

Event loop is running in the main thread, but your endpoint function is executed in different thread. That's why you are getting "There is no current event loop in thread".
You need to get event loop in the main thread and save it somewhere (e.g. in app state):
from asyncio import AbstractEventLoop, sleep
import asyncio
from contextlib import asynccontextmanager
from typing import Annotated, cast

from fastapi import Depends, FastAPI, Request


@asynccontextmanager
async def lifespan(app: FastAPI):
    yield {"event_loop": asyncio.get_event_loop()}


app = FastAPI(lifespan=lifespan)


async def some_coroutine():
    await sleep(2)
    print("Hello, from async function!")


async def get_event_loop(request: Request) -> AbstractEventLoop:
    return cast(AbstractEventLoop, request.state.event_loop)


@app.get("/")
def my_non_async_endpoint(
    event_loop: Annotated[AbstractEventLoop, Depends(get_event_loop)],
):
    t = asyncio.run_coroutine_threadsafe(some_coroutine(), loop=event_loop)
    t.result(timeout=3.0)
    return {"Hello": "world"}

